& > :is(toolbarbutton, toolbarseparator, toolbaritem) {
  /* Prevent children from getting events */
  pointer-events: none;
  justify-content: center;
  flex: 1;
}

&[type="separator"][place="palette"] {
  align-items: center;

  & toolbarseparator {
    background-color: currentColor;
    padding: 0;
  }
}
